# -*- coding: utf-8 -*-
import json

t = {}

t["451"] = "Tại trạm thu phí ở điểm đến, hãy giải thích cho nhân viên tính phí về nơi đã đi vào và thanh toán."
t["452"] = "Hỏa hoạn trong hầm thì lánh nạn là ưu tiên hàng đầu, nên việc đánh giá thấp nguy hiểm mà ở lại trong xe là hành động nguy hiểm; phải tắt máy rồi để nguyên chìa khóa cắm ở ổ, nhanh chóng xuống xe và lánh nạn."
t["453"] = "Để phòng ngừa tai nạn do sự thích nghi với bóng tối (hiện tượng khi đi từ nơi sáng vào nơi tối, ban đầu không nhìn thấy nhưng theo thời gian bắt đầu nhìn thấy) và sự thích nghi với ánh sáng (hiện tượng dần thích nghi với ánh sáng mạnh khi ra từ nơi tối đến nơi sáng), khi đi qua hầm phải giảm tốc độ 10~20% so với bình thường và nhất thiết phải bật các đèn như đèn pha, đèn định vị chiều rộng xe, đèn hậu. Ngoài ra, để phòng ngừa đóng băng và tai nạn thứ cấp v.v., cần đảm bảo khoảng cách an toàn nhiều hơn so với đường thông thường và cần chuẩn bị cho việc phanh gấp."
t["454"] = "① Lực phanh giảm. ③ Có thể bị trượt sang ngang do phanh lệch. ④ ABS giúp giảm lực ly tâm trên đường mưa, và ở tốc độ nhất định thì quãng đường phanh được giảm ở mức độ nào đó."
t["455"] = "Khi xảy ra động đất, việc lái xe rất nguy hiểm. Hãy hết sức chú ý, tránh giao lộ mà dừng xe ở bên phải đường, nghe kỹ thông tin trên radio và nếu gần đó có cảnh sát thì hành động theo chỉ dẫn. Khi bỏ xe lại để lánh nạn, hãy tắt máy và để nguyên chìa khóa cắm ở ổ rồi lánh nạn."
t["457"] = "① Phải tắt máy để đề phòng nguy cơ nổ v.v. ③ Phải dừng xe sát vào tường bên thì xe cấp cứu v.v. mới có thể lưu thông. ④ Phải để nguyên chìa khóa cắm ở ổ thì khi phát sinh tình huống khác mới có thể xử lý."
t["458"] = "② Chủ yếu xảy ra khi chạy tốc độ cao. ③ Vết trên mặt đường do hiện tượng trượt là tài liệu quan trọng trong việc xử lý tai nạn."
t["459"] = "Trường hợp xe văng khỏi làn đường chủ yếu xảy ra khi đánh vô lăng gấp trên đường cong. Ngoài ra, nếu gai lốp bị mòn, áp suất lốp quá cao hoặc mặt đường trơn thì lực ma sát giữa mặt đường và lốp giảm, xe có thể văng khỏi đường hoặc lấn qua vạch tim đường."
t["460"] = "Cách xử lý khi xe bị hỏa hoạn trong lúc chạy trên đường cao tốc: 1. Di chuyển xe ra lề đường. 2. Tắt máy và nhanh chóng xuống xe. 3. Nếu có thể dập lửa ban đầu thì dùng bình chữa cháy trang bị trên xe để dập lửa. 4. Khi dập lửa ban đầu thất bại thì xe có thể phát nổ nên hãy lánh ra xa. 5. Gọi báo cháy xe cho 119 v.v."
t["461"] = "Công trường đường bộ gồm các đoạn cảnh báo - chuyển tiếp - thi công - kết thúc. Trong đó, đoạn chuyển tiếp là đoạn giảm số làn đường, là đoạn cần chuyển làn đường. Để lưu thông an toàn thì việc chuyển làn đường trước và đi chậm là bắt buộc."
t["462"] = "Để ngăn hiện tượng bốc hơi (hiện tượng lóa khiến hình ảnh biến mất), không nhìn thẳng vào ánh đèn của xe hướng ngược lại."
t["463"] = "Hiện tượng bốc hơi xảy ra khi cả hai xe đi ngược chiều nhau đều bật đèn pha chiếu xa."
t["464"] = "Lái xe ban đêm và sự suy giảm tỉnh táo. Tầm nhìn khi lái xe ban đêm bị giới hạn trong phạm vi ánh đèn pha chiếu tới, tầm nhìn đó so với ban ngày chỉ thấy được mặt đường và ánh đèn hậu của xe phía trước nên trở thành tầm nhìn rất đơn điệu. Vì vậy, người lái vô thức quen với tầm nhìn đơn điệu và rơi vào một trạng thái tê liệt cảm giác. Khi đó, tất yếu chuyển động của nhãn cầu không còn linh hoạt nên phản ứng với kích thích cũng trở nên chậm chạp. Khi hiện tượng này gia tăng thì phản ứng của cơ bắp hay sóng não cũng suy giảm, dần dần đi đến trạng thái buồn ngủ. Việc lái xe trong trạng thái độ tỉnh táo suy giảm như vậy được gọi là 'lái xe trong trạng thái suy giảm tỉnh táo'."
t["465"] = "Vì việc đảm bảo tầm nhìn khó hơn so với ban ngày nên cần phải chú ý."
t["467"] = "Không được tự ý can thiệp vào hệ thống dây điện, và để bình gas butan dùng một lần trong xe là nguy hiểm. Bật lửa dùng một lần không có thiết bị chống nổ nên để trong xe vào mùa hè là nguy hiểm."
t["468"] = "Để phòng ngừa va chạm với xe phía trước, hãy đảm bảo đủ khoảng cách an toàn và chuẩn bị để có thể phanh bất cứ lúc nào nhằm đề phòng nguy hiểm. Đề phòng trường hợp bất khả kháng phải va chạm, hãy đạp mạnh chân phanh để giảm tốc nhằm giảm thiểu thiệt hại. Nếu đánh vô lăng gấp sang trái vượt qua vạch tim đường thì có thể xảy ra tai nạn với xe đang chạy ở chiều ngược lại. Ngoài ra, việc nhắm mắt và thao tác cần gạt nước, đèn pha chiếu xa không liên quan đến việc giảm thiệt hại do va chạm."
t["469"] = "Nếu áp suất lốp của xe chạy tốc độ cao không đủ thì xảy ra hiện tượng sóng đứng (standing wave), và nếu xe chạy tốc độ cao với lốp đã mòn đi qua nơi đọng nước thì xảy ra hiện tượng màng nước (hydroplaning). Hiện tượng phai phanh (fade) là hiện tượng khi sử dụng bàn đạp phanh quá mức, hệ số ma sát của má phanh và lớp lót giảm khiến lực phanh xấu đi và bị trượt. Hiện tượng khóa hơi (vapor lock) và hiện tượng phai phanh (fade) là các hiện tượng xuất hiện do trục trặc của hệ thống phanh."
t["470"] = "Nghị định thi hành Luật Giao thông đường bộ Phụ lục 6: trường hợp người ngồi cùng dưới 13 tuổi thì phạt hành chính 60.000 won. Điều 31 Thông tư thi hành Luật Giao thông đường bộ (Lý do không thắt dây an toàn) khoản 4: khi xe ưu tiên đang được vận hành đúng công dụng vốn có của nó."
t["471"] = "Đối với người lái, khi điều chỉnh ghế thì thường ít khi điều chỉnh gối tựa đầu. Do đó, gối tựa đầu có thể giữ cố định đầu khi bị va chạm do tai nạn giao thông cũng cần được điều chỉnh cho vừa với đầu của mình."
t["472"] = "Giao lộ, trên cầu, trong hầm v.v. là những nơi cấm vượt xe, khi vào hầm xảy ra hiện tượng thích nghi với bóng tối, và trường hợp vạch kẻ đường là vạch đứt màu trắng thì có thể chuyển làn đường."
t["473"] = "① Khi thay đổi hướng đi mà không ra tín hiệu, dù không gây cản trở giao thông khác thì vẫn thuộc đối tượng vi phạm luật giao thông do không ra tín hiệu. ② Sau khi thay đổi hướng đi xong phải ngừng tín hiệu ngay. ③ Khi thay đổi hướng đi mà không ra tín hiệu thì xe con và xe khách v.v. thuộc đối tượng bị phạt vi phạm 30.000 won. ④ Khi thay đổi hướng đi trên đường cao tốc thì ra tín hiệu từ điểm cách 100 mét trước cho đến khi hoàn tất việc thay đổi hướng đi."
t["474"] = "Mọi người lái xe không được vượt xe phía trước trong trường hợp có xe khác đang đi song song với xe phía trước ở bên trái xe đó, hoặc trường hợp xe phía trước đang vượt hoặc định vượt xe khác. (Điều 21, Điều 22 Luật Giao thông đường bộ)"
t["475"] = "Tốc độ của xe muốn vượt xe khác chỉ được phép vượt trong phạm vi tốc độ tối đa của đường đó."
t["476"] = "Điểm đỗ khẩn cấp thì ngoài xe ưu tiên của cảnh sát và xe cứu hỏa, xe thông thường cũng có thể dừng hoặc đỗ."
t["477"] = "Cái gọi là quãng đường dừng của xe - từ khi người lái cảm thấy nguy hiểm, đạp bàn đạp phanh cho đến khi xe thực sự dừng lại - sẽ dài ra khi lái xe trong tình trạng mệt mỏi và uống rượu bia, khi trọng lượng xe nặng hoặc tốc độ càng nhanh, và khi tình trạng mòn lốp càng nghiêm trọng."
t["478"] = "Mọi người lái xe không được chở người hoặc chở hàng vượt quá tiêu chuẩn an toàn khi vận hành về số người ngồi, trọng lượng chở và dung tích chở. Tuy nhiên, khi được sự cho phép của Trưởng đồn cảnh sát quản lý nơi xuất phát thì không áp dụng điều này. (Điều 39 Luật Giao thông đường bộ)"
t["479"] = "Giữ khoảng cách với xe phía trước lớn hơn quãng đường dừng, giảm tốc đủ để không đâm vào xe phía trước và đảm bảo khoảng cách an toàn. (Điều 19 Luật Giao thông đường bộ)"
t["480"] = "① Trường hợp người lái không thắt dây an toàn thì bị phạt vi phạm 30.000 won. ② Thông thường, chấn thương kiểu roi quất ở vùng cổ xảy ra nhiều hơn ở loại 2 điểm. ③ Nếu trẻ em dưới 13 tuổi không thắt dây an toàn thì bị phạt hành chính 60.000 won. ④ Dây an toàn được phân loại thành loại 2 điểm, 3 điểm, 4 điểm tùy theo cách thắt."
t["481"] = "Người ngồi trên xe phải thắt dây an toàn vì sự an toàn, và ngoài trường hợp xuất động vì nhiệm vụ khẩn cấp thì người lái xe ưu tiên cũng nhất thiết phải thắt dây an toàn. (Điều 50 Luật Giao thông đường bộ)"
t["482"] = "Trường hợp có bệnh nhân nghi bị gãy cột sống do tai nạn giao thông thì không được di chuyển nếu không phải trường hợp khẩn cấp. Vì nếu không được xử lý thích hợp trước khi di chuyển thì nguy cơ làm nặng thêm tổn thương thần kinh không thể hồi phục là rất lớn. Do đó, nếu buộc phải di chuyển để phòng ngừa nguy cơ tai nạn thứ cấp v.v., thì phải dùng nẹp cố định phần cột sống rồi ưu tiên lánh đến nơi an toàn."
t["483"] = "Để kiểm tra tình trạng ý thức, có các cách như thử bắt chuyện với người bị thương, vỗ nhẹ vào vai, hoặc véo cánh tay để kiểm tra."
t["484"] = "Điều 54 Luật Giao thông đường bộ (Xử lý khi xảy ra tai nạn) khoản 5: người lái xe ưu tiên, xe đang chở người bị thương, xe bưu phẩm và tàu điện mặt đất v.v. trong trường hợp khẩn cấp có thể để người ngồi cùng v.v. thực hiện việc xử lý tai nạn hoặc báo cảnh sát và tiếp tục lái xe."
t["485"] = "Người lái xe ưu tiên hoặc xe đang chở người bị thương và xe vận chuyển bưu phẩm v.v. trong trường hợp khẩn cấp có thể để người ngồi cùng thực hiện việc xử lý cần thiết hoặc báo cáo và tiếp tục lái xe. (Điều 54 khoản 5 Luật Giao thông đường bộ)"
t["486"] = "Nguy cơ tai nạn roadkill xảy ra khi động vật bất ngờ xuất hiện khiến không kịp ứng phó, nên trên những đoạn đường có khả năng cao động vật xuất hiện thì tốt nhất nên giảm tốc độ khi lái xe."
t["487"] = "Dịch vụ cứu kéo khẩn cấp của Tổng công ty Đường bộ Hàn Quốc (tổng đài 1588-2504) là chế độ kéo miễn phí những xe đang dừng trên đường cao tốc do tai nạn hoặc hỏng hóc có nguy cơ gây tai nạn thứ cấp đến khu vực an toàn như trạm dừng nghỉ, trạm điều hành, điểm nghỉ chống buồn ngủ gần đó."
t["488"] = "Theo Cơ quan Quản lý Dịch bệnh, xác động vật có nguy cơ lây nhiễm nên không được trực tiếp chạm vào, và khi xảy ra tai nạn thì báo cho chính quyền địa phương hoặc cơ quan quản lý đường bộ và tổng đài mã vùng +120 (dịch vụ tư vấn hướng dẫn đời sống) để được trợ giúp; động vật bị tai nạn theo luật hiện hành thuộc dạng đồ vật nên trong trường hợp đã ngăn ngừa nguy hiểm để phòng tai nạn thứ cấp và bảo đảm lưu thông thông suốt thì không báo cũng được."
t["489"] = "Quy tắc an toàn giao thông bản sửa đổi lần 2 năm 2021. Các kỹ thuật hành vi để kiểm soát cơn giận gồm kỹ thuật tạm dừng (time-out), kỹ thuật nút dừng (stop button), kỹ thuật luyện tập thư giãn căng thẳng. ① Phương pháp kiểm soát cơn giận bằng cách tạm thời thoát ra khỏi tình huống đang sôi sục cảm xúc, dành chút thời gian và tìm lại sự bình tĩnh trong tâm gọi là kỹ thuật tạm dừng. ② Phương pháp kiểm soát cơn giận bằng cách ngừng những suy nghĩ tiêu cực gây ra cơn giận và hồi tưởng, tập trung vào một cảnh hạnh phúc đã nghĩ sẵn trong 1-2 phút gọi là kỹ thuật nút dừng. ③ Kỹ thuật câu hỏi hồi tưởng trải nghiệm không thuộc phương pháp kiểm soát cơn giận. ④ Phương pháp lặp đi lặp lại việc làm căng hết mức rồi thả lỏng từng bộ phận cơ thể như hai tay, chân, bụng dưới, ngực, vai để đạt trạng thái thoải mái gọi là kỹ thuật luyện tập thư giãn căng thẳng."
t["490"] = "Nếu do mưa lớn mà hầm chui bị ngập nước tới cản xe hoặc hơn một nửa bánh xe bị ngập nước thì xe không thể đi qua. Ngoài ra, khi đi qua khu vực như trên với tốc độ nhanh thì xe đẩy nước ra làm mực nước phía trước dâng cao và nước có thể lọt vào động cơ. Nếu xe bị chết máy ở khu vực ngập nước, việc đề máy lại sẽ làm hỏng động cơ."
t["491"] = "Khi xảy ra tình huống khẩn cấp, cần kiểm tra có nguy hiểm hay không và quan sát phản ứng của bệnh nhân, yêu cầu người xung quanh trợ giúp, và tùy theo nhu cầu cần khai thông đường thở để bệnh nhân có thể thở, đồng thời phải yêu cầu cứu hộ."
t["492"] = "Nếu vô lăng rung mạnh thì có thể lốp bị thủng hoặc bánh xe bị tuột nên nhất thiết phải dừng xe ở nơi an toàn và kiểm tra."
t["493"] = "Phải chụp cận cảnh và chụp từ xa vị trí hư hỏng, và phải chụp cả trạng thái bánh xe đang xoay hướng nào thì sau này mới có ích cho việc làm rõ tai nạn."
t["494"] = "Trước khi lái xe đường dài, phải kiểm tra tình trạng mòn lốp, áp suất lốp, các loại dầu, cần gạt nước và nước rửa kính, các loại đèn v.v."
t["495"] = "① 1 năm. ② Trường hợp bị lập hồ sơ hình sự thì là lý do bị hủy. ③ Trường hợp lái xe chưa được đăng ký theo Luật Quản lý ô tô hoặc chưa được cấp phép vận hành tạm thời thì bị hủy giấy phép lái xe, còn việc đã đăng ký nhưng lái xe mà không gắn biển số đăng ký thì không phải là lý do hủy giấy phép. (Điều 93 Luật Giao thông đường bộ)"
t["496"] = "Người không nộp tiền phạt vi phạm trong thời hạn nộp thì trong vòng 20 ngày kể từ ngày kế tiếp ngày hết hạn nộp phải nộp số tiền bằng tiền phạt vi phạm đã được thông báo cộng thêm 20/100. (Điều 164 khoản 2 Luật Giao thông đường bộ)"
t["497"] = "Nếu từ 121 điểm trở lên trong 1 năm, từ 201 điểm trở lên trong 2 năm, từ 271 điểm trở lên trong 3 năm thì hủy giấy phép. (Thông tư thi hành Luật Giao thông đường bộ Phụ lục 28)"
